USE [master]
GO
IF DB_ID(N'steam') IS NOT NULL
BEGIN
    ALTER DATABASE [steam] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE [steam];
END
GO
CREATE DATABASE [steam]
go
USE [steam]
GO
