INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'STAR WARS(tm) Jedi Knight - Mysteries of the Sith(tm)', N'2009', 0, 0, 1, 0, 0, 3, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Actio', N'USD', 2.99, 2.99, N'It is five years after Kyles victory over the seven dark Jedi. Invading Imperial forces advance upon a quiet Rebel outpost interrupting Kyles training of a brave new Jedi Mara Jade. First introduced in Timothy Zahns award-winning Star Wars novel Heir to the Empire Mara Jade blends her past experiences as a one time smuggler and Emperors Hand with her apprenticeship as a Jedi Knight. Armed with four new weapons and five new Force powers Mara must secure supplies desperately needed by the New Republic while Kyle believing it a part of his destiny pursues the secret treasures shrouded in an ancient Sith temple.', N'http://cdn.akamai.steamstatic.com/steam/apps/32390/header.jpg?t=1462236602', N'English* French* Italian* Spanish**languages with full audio support', N' Single Player Multiplayer', N'http://www.lucasarts.com')
