INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Kinetic Void', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'True', N'True', N' Indie Action Simulatio', N'USD', 19.99, 19.99, N'Kinetic Void is a 3D space adventure with a focus on customization and enjoyable space simulation. The shipyard allows players to construct their ship piece by piece. Ships can be as simplistic as a cockpit a hull a engine and a gun or as complex as a player wants.  Each module has available subsystems which can be applied to strengthen specific attributes of the ship and when damaged those subsystems may be destroyed.  While in space flight interactions between objects are governed by the physics engine. Running into an asteroid at high speed will damage your ship potentially with catastrophic effects. Using the Kinetic Field Generator (KFG) in game will allow your ship to create an artificial gravity around the ship both protecting the ship as well as allowing your ship to fly freely through space.  This field will also enable the Micro Warp Drive catapulting your ship far into space in a matter of seconds.', N'http://cdn.akamai.steamstatic.com/steam/apps/227160/header.jpg?t=1447357131', N'English**languages with full audio support', N' Single Player', N'http://www.BadlandStudio.com/Kinetic-Void')
