INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Uprising44: The Silent Shadows', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Action Strategy', N'USD', 5.99, 5.99, N'Uprising44: The Silent Shadows[/b] combines third-person action play with real-time strategy. It is a unique combination of the two modes of play and has an in-depth and interesting story-line which has not yet been used in WWII computer games - the greatest civilian Uprising against Nazi occupying forces - the Warsaw Uprising. It is a story of the Silent Shadows - forerunners of modern day special forces - paratroopers dropped behind enemy lines to organize resistance and use diversionary tactics in the fight against the forces of the Third Reich. An appropriate audio-visual setting combined with cover system (an excellent proven method of game play) the story-line and diverse settings ensure a dynamic and enjoyable game not only for players familiar with this type of theme but also those merely wanting casual entertainment.', N'http://cdn.akamai.steamstatic.com/steam/apps/280380/header.jpg?t=1447360458', N'English**languages with full audio support', N' Single Player', N'www.uprising44.com')
