INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Volt', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'True', N'True', N' Indie Actio', N'USD', 1.99, 1.99, N'You were on the way to a recycling process when fortunately for you - and unfortunately for the environment - you accidentally ran off. Now your goal is to escape from the facility which is an extremely difficult task due to the fact that you are a battery without legs. Equipped with a limited number of electric beams you can connect to walls move or destroy objects turn switches and charge generators. You also have the ability to jump or push off the walls - the rest is up to physics and gravity.', N'http://cdn.akamai.steamstatic.com/steam/apps/290280/header.jpg?t=1448992612', N'English', N' Single Player', N'http://www.quantizedbit.com/volt')
