INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Project Temporality', N'2014', 0, 0, 1, 0, 0, 1, 19, N'True', N'False', N'False', N'True', N'False', N'False', N' Indie Action Adventure', N'USD', 14.99, 14.99, N'Experience the mind bending power of single player cooperation.Project Temporality is a third person action/puzzle game built around the concept of allowing the player to play with time. Thanks to our propriety engine Sparta 3D we make the fourth dimension as available as the other three. Just as with a VCR you can rewind time or fast-forward through it seamlessly.Combining this and our time line concept you will solve mind-bending puzzles by giving yourself a helping hand. Any time you need a friend you can be that friend. Create a new timeline at any time/any place there are no restrictions. This game is all about giving you full freedom in four dimensions.Solve puzzles involving lasers mirrors force fields trap doors platforms keys etc. Exploit time to do the impossible. Explore the world and see into the mind of its people. We hope that you will enjoy the result of our years of evenings and weekends.', N'http://cdn.akamai.steamstatic.com/steam/apps/290320/header.jpg?t=1447361034', N'English Spanish', N' Single Player', N'http://www.defrostgames.com')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Armello', N'2015', 0, 0, 1, 2, 75, 1, 50, N'True', N'False', N'False', N'True', N'True', N'True', N' Indie Adventure Strategy RPG', N'USD', 19.99, 19.99, N'Armello is a grim fairy-tale board game come to life. Full of swashbuckling adventure combining deep tactical card play rich tabletop strategy and RPG elements. Wage epic single and multiplayer battles cast spells hire agents and prepare poisons and ruses on your quest for the throne!', N'http://cdn.akamai.steamstatic.com/steam/apps/290340/header.jpg?t=1473927558', N'English Italian Spanish Dutch Japanese Korean Polish Portuguese-Brazil Russian French German Simplified Chinese', N' Single Player Multiplayer', N'http://www.armello.com')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Micro', N'2014', 0, 0, 1, 0, 0, 1, 11, N'True', N'False', N'False', N'True', N'True', N'True', N' Indie Casual', N'USD', 4.99, 4.99, N'Micron is a unique fusion of puzzle and rhythm gameplay. Place pieces on the board to deflect bullets of energy that fire to the beat. Guide the bullets to the exit through 51 challenging levels -- and 12 bonus levels -- featuring a variety of distinctive soundscapes. Your solutions create the music.', N'http://cdn.akamai.steamstatic.com/steam/apps/290380/header.jpg?t=1447361035', N'English', N' Single Player', N'http://microngame.com')
