INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Countless Rooms of Death', N'2015', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Indie Adventure', N'USD', 0.99, 0.99, N'Countless Rooms of Death is a puzzle / adventure game with a horror atmosphere. There are no weapons or real enemies; instead we aim to bully your mind. All you the player have is a flashlight with which to find your way through a dark labyrinth solving puzzles to acquire keys which will allow you to enter the next level. There are strange happenings and whispered voices to investigate and several ways to meet your demise within the labyrinth. Strange lights and shapes will try to distract you from your path to freedom. The story unfolds in the form of medical records which with the passage of time will help you to remember how you got here in the first place.', N'http://cdn.akamai.steamstatic.com/steam/apps/341380/header.jpg?t=1447366742', N'English', N' Single Player', N'http://www.hcpgames.com')
