INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Bio Menace', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N' ', 0, 0, N'You are Snake Logan a top CIA operative who likes to do things his own way. Metro City has fallen under the attack of hideous mutants and your mission is to fly recon over the city and report back. While circling over the city youre shot down by hostile forces and forced to crash land on the streets of Metro. Grabbing what supplies you can find you are out to discover the source of these mutants and especially the guy who shot you down!', N'http://cdn.akamai.steamstatic.com/steam/apps/358180/header.jpg?t=1447371216', N'English', N' Single Player', N'https://3drealms.com/catalog/bio-menace_42/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Blake Stone: Aliens of Gold', N'2015', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N'USD', 4.99, 4.99, N'Wolfenstein 3D took you into the past thrusting you into a world at war. Blake rockets you into the future where a sinister madman using genetics to create an army of bizarre creatures is waging war on Earth. Blake has more of everything! More action more enemies more levels more firepower more graphics more animation more pitfalls and more features. Like built-in auto-mapping so you never have to worry about getting lost in the game.', N'http://cdn.akamai.steamstatic.com/steam/apps/358190/header.jpg?t=1464632765', N'English', N' Single Player', N'https://3drealms.com/catalog/blake-stone_15/')
