INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Monster Bash', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N'USD', 4.99, 4.99, N'Johnny Dashs bash em and smash em adventure takes him into the evil Under World of Count Chuck. The story starts when Johnnys dog Tex is kidnapped by the Count along with hundreds of other pet dogs and cats. The friendly bed monster under Johnnys bed tells Johnny where Tex was taken and how Johnny can use his secret closet passageway to get to the Under World himself. Count Chuck plans to turn their pets into an army of undead monsters. Johnny grabs his slingshot and leaps into his closet. The Count will not turn his dog Tex into a monster not if he can stop him!', N'http://cdn.akamai.steamstatic.com/steam/apps/358210/header.jpg?t=1447371221', N'English', N' Single Player', N'https://3drealms.com/catalog/monster-bash_38/')
