INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Paganitzu', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Action Adventure', N'USD', 4.99, 4.99, N'Journey into an Aztec pyramid and survive the adventure of a lifetime! No other game forces you to die in order to complete it! Thats just one of many incredible plot twists in this excellent puzzle-oriented arcade-adventure game.Guide Alabama Smith (Al) into a vast and dangerous Aztec pyramid. Confront traps of increasing perplexity and face unfathomable creatures in this innovative arcade game that tests your mind more than your finger speed.', N'http://cdn.akamai.steamstatic.com/steam/apps/358230/header.jpg?t=1447371226', N'English', N' Single Player', N'https://3drealms.com/catalog/paganitzu_14/')
