INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Cosmos Cosmic Adventure', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Action Adventure', N'USD', 4.99, 4.99, N'Whats green with red spots has suction hands and has an overbite like Bart Simpson? Of course the answer is Cosmo! Cosmo is a young alien on his way to visit Disney World with his parents. That is until their ship is struck by a blazing comet forcing them to land on an uncharted planet.While his Dad repairs the ship Cosmo heads off to explore the strange planet. Upon returning both his Mom and Dad are gone and big scary alien footprints are all around his ship! Oh no! Have Cosmos parents been captured? Possibly to be eaten? Well Cosmo is off to the rescue.', N'http://cdn.akamai.steamstatic.com/steam/apps/358250/header.jpg?t=1447371229', N'English', N' Single Player', N'https://3drealms.com/catalog/cosmos-cosmic-adventure_37/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Crystal Caves', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N'USD', 4.99, 4.99, N'Enter an underground world of treasures and traps in Crystal Caves a colorful EGA game that rivals any commercial game with its arcade quality puzzles and graphics. As Mylo Steamwitz enter cave after cave of adventure gathering teasures and evading countless hazards.Crystal Caves is a mixing of Nintendos Mario Brothers Commander Keen and Indiana Jones. As with all Apogee games a high priority has been placed on solving ingenious puzzles built into the game.', N'http://cdn.akamai.steamstatic.com/steam/apps/358260/header.jpg?t=1447371233', N'English', N' Single Player', N'https://3drealms.com/catalog/crystal-caves_7/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Death Rally (Classic)', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' racing', N'USD', 4.99, 4.99, N'You start out from the bottom of the ranking list. Your objective: earn money in the blitzkrieg-battle races. Fight hard for each precious championship point. Fellow competitors are showering you in a constant hail of bullets. Each race is deadly contest - a matter of life or death. Death Rally takes the top-down racing game to a level youve never experienced before.', N'http://cdn.akamai.steamstatic.com/steam/apps/358270/header.jpg?t=1447371236', N'English', N' Single Player', N'https://3drealms.com/catalog/death-rally_13/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Alien Carnage / Halloween Harry', N'2014', 0, 0, 2, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N' ', 0, 0, N'Starring hero Halloween Harry Alien Carnage is an impressive game with no detail overlooked. Professional musical soundtrack brilliant full-VGA graphics non-stop animation and huge start-game and end-game cinematics.If Duke Nukem has a twin separated at birth its got to be Halloween Harry! Harry has an armory of weapons he can find and use besides the devastating flamethrower that he starts the game with. And Harrys jetpack takes him to spots on a level that normal heroes could not reach.', N'http://cdn.akamai.steamstatic.com/steam/apps/358280/header.jpg?t=1447371238', N'English', N' Single Player', N'https://3drealms.com/catalog/alien-carnage_48/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Hocus Pocus', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Action Adventure', N'USD', 4.99, 4.99, N'Terexin leader of the Council of Wizards is sending the young sorcerer Hocus on a special mission to prove his worthiness.', N'http://cdn.akamai.steamstatic.com/steam/apps/358290/header.jpg?t=1447371241', N'English', N' Single Player', N'https://3drealms.com/catalog/hocus-pocus_20/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Major Stryker', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'True', N'False', N'True', N'False', N'True', N' Actio', N'USD', 2.99, 2.99, N'In the not-so-distant future the calamity of World War III led to eventual world peace. But it didnt last. Earth was invaded by alien marauders - the Kretons. Earths united military force still depleted after the mighty onslaught of WWIII was not nearly sufficient to repel the numerous Kreton attacks.It was discovered that the Kretons had used a wormhole to invade our region of space from their home worlds. And with that knowledge Earth called into action Major Harrison Stryker hero of WWIII to travel back through the wormhole and destroy the Kretons home world headquarters.With almost no chance of success you accept the mission...', N'http://cdn.akamai.steamstatic.com/steam/apps/358300/header.jpg?t=1447371244', N'English', N' Single Player', N'https://3drealms.com/catalog/major-stryker_47/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Blake Stone: Planet Strike', N'2015', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N'USD', 4.99, 4.99, N'Its the 22nd century: Galactic travel is commonplace peace is at hand and the future looks bright - until Goldfires plan to unleash an army of military mutants shocks the galaxy. Dr. Goldfire a brilliant bio-scientist whose morbid research led to incredible genetic improvements in humanoids and aliens has gone power crazy.And only the galaxys best agent Blake Stone has a chance to infiltrate Goldfires secret fortress on a remote planet and end the evil before its too late. Up against absurd odds and the most hideous genetic creatures and armed personnel ever amassed its up to you to help Blake in his most dangerous mission ever classified: Planet Strike!', N'http://cdn.akamai.steamstatic.com/steam/apps/358310/header.jpg?t=1447371244', N'English', N' Single Player', N'https://3drealms.com/catalog/planet-strike_21/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Realms of Chaos', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Action Adventure', N'USD', 4.99, 4.99, N'Realms of Chaos is an exciting side-scrolling platform game with an innovative mix of action adventure mysticism and role-playing thats never been seen in this style of game.Set in the fantastic world of Mysteria Realms of Chaos is the first of many adventures of Endrick and Elandra a brother and sister duo who find themselves on a journey to save the many realms of Mysteria from a dark evil shadow that has engulfed their world and has turned all of the inhabitants into fierce enemies.', N'http://cdn.akamai.steamstatic.com/steam/apps/358320/header.jpg?t=1447371247', N'English', N' Single Player', N'https://3drealms.com/catalog/realms-chaos_9/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Pharaohs Tomb', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Adventure', N' ', 0, 0, N'Pharaohs Tomb is an arcade-adventure game set in a huge Egyptian pyramid. Explore 20 uniquely-dangerous levels riddled with ingenious puzzles and traps. You start with five lives and a few spears which can he thrown at offending denizens that patrol the pyramid. Pharaohs Tomb consists of four unique volumes which concludes with Nevadas Revenge.', N'http://cdn.akamai.steamstatic.com/steam/apps/358330/header.jpg?t=1447371249', N'English', N' Single Player', N'https://3drealms.com/catalog/pharaohs-tomb_46/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Word Rescue', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Action Adventure', N'USD', 4.99, 4.99, N'Word Rescue is an incredible adventure for kids who want to rescue all the stolen words from the mean ol Gruzzles. The Gruzzles cant read and they dont want anyone else to read. So theyve stolen the words out of all of our books!Benny Bookworm needs your help to stop the Gruzzles. He needs you to reunite the stolen words with their meanings. Once you join all the words with their pictures Benny will put them back into the books.', N'http://cdn.akamai.steamstatic.com/steam/apps/358340/header.jpg?t=1447371252', N'English', N' Single Player', N'https://3drealms.com/catalog/word-rescue_32/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Secret Agent', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N'USD', 4.99, 4.99, N'You are agent 006 - top agent of the governments secret organization committed to protecting the world against terrorists and power-mad criminals.Your mission: to parachute into a high -security island outpost and secure the plans to the ultimate satellite laser weapon which was recently stolen from the government. In the wrong hands this weapon could mean world control by the DVS the worlds most dangerous terrorist organization. You will isolated from outside help as you parachute into the secret island fortress of the DVS. You will need to knock out the vast security system bypass dozens of extreme traps overcome hundreds of multi-talented guards (such as thugs ninjas sharp-shooters knife throwers sentries dogs and many robots) and find the missing blue prints. If possible take out the devious leader of the DVS (sorry no file picture available).', N'http://cdn.akamai.steamstatic.com/steam/apps/358350/header.jpg?t=1447371255', N'English', N' Single Player', N'https://3drealms.com/catalog/secret-agent_39/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Raptor: Call of the Shadows (1994 Classic Edition)', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N'USD', 4.99, 4.99, N'Become a mercenary of the future and pilot the super-tech Raptor. Embark on interplanetary missions to knock off top competitors of MegaCorp battle against hordes of relentless enemies and spend the bounty to expand your devastating arsenal which can be upgraded with 14 hardcore weapons!Raptor has some of the hottest graphics ever seen in a shareware game and blows away most commercial games too! The graphics will amaze you and the sound will astound you. Its a super star! - Interactive Entertainment', N'http://cdn.akamai.steamstatic.com/steam/apps/358360/header.jpg?t=1447371255', N'English', N' Single Player', N'https://3drealms.com/catalog/raptor_23/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Terminal Velocity', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N'USD', 6.99, 6.99, N'In the far future armadas from surrounding systems have suddenly waged war on Earth destroying crucial installations and major cities - Earth is quickly brought to its knees. You are a pilot from the Ares Squadron flying the fastest most dangerous crafts ever made. You pilot the TV-202 a fighter few can handle. Given that the previous model the TV-101 has chalked up more dead pilots than any experimental craft in history many consider you lucky to be alive. Youre outgunned outmanned and strapped into a flying coffin.', N'http://cdn.akamai.steamstatic.com/steam/apps/358370/header.jpg?t=1447371259', N'English', N' Single Player', N'https://3drealms.com/catalog/terminal-velocity_40/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Wacky Wheels', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Action racing', N'USD', 4.99, 4.99, N'Nothing beats the excitement of playing against friends. In Wacky Wheels you can do just that. Play with a friend in split-screen mode play head-to-head using a modem connection or play via serial (null-modem) cable. Race against challenging computer opponents with adjustable difficulty settings. Wacky Wheels is packed with features: non-stop action and variety heart-racing music and furious 3D point-of-view vivid VGA graphics and animations. Its so much fun youll hate to finish!', N'http://cdn.akamai.steamstatic.com/steam/apps/358380/header.jpg?t=1447371262', N'English', N'', N'https://3drealms.com/catalog/wacky-wheels_16/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Stargunner', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'True', N'False', N'True', N'False', N'True', N' Action Free to play', N' ', 0, 0, N'In the far distant future an epic war for survival takes place...Deep within the Andromeda galaxy the people of Zile grow restless and greedy. The Zilions secretly prepare for a massive strike against the nearby planet Ytima. Fearing such an attack the Ytimians train an elite squad of Stargunners. Their mission: To strike the planet Zile and cripple the Zilions three strongholds where the Zilion war fleets await. If the Stargunners can surprise the Zilions on their own planet and wipe out their fleet then good will triumph over evil once again.', N'http://cdn.akamai.steamstatic.com/steam/apps/358390/header.jpg?t=1471970741', N'English', N' Single Player', N'https://3drealms.com/catalog/stargunner_45/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Shadow Warrior (Classic)', N'2014', 0, 0, 1, 0, 73, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N' ', 0, 0, N'Lo Wang. Master ninja assassin for 20 years. A Shadow Warrior. Shadow Warriors are the best of the best and Lo Wang was the best of the Shadow warriors. Every top company in Japan had a Shadow Warrior... a protector a negotiator a cleaner.', N'http://cdn.akamai.steamstatic.com/steam/apps/358400/header.jpg?t=1447371265', N'English', N' Single Player Multiplayer', N'https://3drealms.com/catalog/shadow-warrior_10/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Rise of the Triad: Dark War', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N'USD', 6.99, 6.99, N'You are part of an elite group of operatives called HUNT (High-risk United Nations Taskforce) and you must stop a maniac cult leader from killing millions of people. While scouting a remote island you are suddenly surrounded by enemy troops with guns blaring. In the distance you see your boat--your only chance to escape--explode into matchsticks. In front of you is a huge fortress monastery and your only chance to stop the madness. You are equipped with awesome high-tech weaponry such as heat-seeking missiles split missiles and the Flamewall cannon which leaves a trail of charred skeletons in its wake. Youll also find magical instruments and weapons so incredible they defy description.', N'http://cdn.akamai.steamstatic.com/steam/apps/358410/header.jpg?t=1464638671', N'English', N' Single Player', N'https://3drealms.com/catalog/rise-triad-dark-war_44/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Xenophage: Alien Bloodsport', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N' ', 0, 0, N'Xenophage is a fighting game in the same genre as Mortal Kombat. This game features scrolling arenas that also zoom in and out depending on how far apart the fighters are from each other. This is a unique feature in fighting games. The fighters all come from unique alien planets so they look very cool and unusual. Its up to you to figure out their special abilities and moves.', N'http://cdn.akamai.steamstatic.com/steam/apps/358420/header.jpg?t=1447371268', N'English', N' Single Player', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Dark Ages', N'2014', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'True', N' Actio', N' ', 0, 0, N'In Dark Ages youre the Prince of the Great Kingdom who as a child watched the King - your father - die at the hands of Garth a power mad warlord with uncanny magical abilities.  Garth sent you away from the Great Kingdom to be raised as a peasant and to never fulfill your destiny as the future King.  But Garth made a terrible mistake.  The very peasant he chose to raise you was once the Kingdoms greatest hero long since retired and forgotten.  And over the years you were raised as a warrior and as champion of justice and the time has come for you to claim your heritage and free the Great Kingdom from the Dark Age of Garth.', N'http://cdn.akamai.steamstatic.com/steam/apps/358440/header.jpg?t=1447371274', N'English', N' Single Player', N'None')
