INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'404Sight', N'2015', 0, 0, 1, 0, 0, 1, 19, N'False', N'True', N'False', N'True', N'False', N'False', N' Indie Actio', N' ', 0, 0, N'404Sight is a free game made in support of net neutrality. Its a 3D playground runner influenced by parkour running with the addition of a special ping ability that reveals areas that can speed the player up or slow them down. Hidden fast and slow lanes become visible so it takes a bit of planning to plot a course through a world full of hazards - especially when the internet service providers themselves are actively trying to impede the players progress. In 404sight the player attempts to traverse a level as quickly as possible without getting throttled by the ISPs who actively throws slow tiles and inhibitors in their way.', N'http://cdn.akamai.steamstatic.com/steam/apps/361630/header.jpg?t=1447372231', N'English**languages with full audio support', N' Single Player', N'http://404sight.com/')
