INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Accidental Runner', N'2015', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Indie Actio', N' ', 0, 0, N'Tired of easy stuff? Willing to feel anger and frustration? This is your game. I bet you wont beat it. Not even the first level.', N'http://cdn.akamai.steamstatic.com/steam/apps/361660/header.jpg?t=1447372242', N'English', N' Single Player Multiplayer', N'None')
