INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Knight & Damsel', N'2015', 0, 0, 1, 1, 0, 1, 0, N'True', N'False', N'False', N'True', N'False', N'False', N' Indie Action Casual', N'USD', 9.99, 3.99, N'Knight & Damsel is a two-player uncooperative multiplayer game set on a papercraft stage that subverts the age-old tale of knights saving damsels with the knight and damsel competing to rescue the other!In Knight & Damsel players attempt to delay their opponent so their chosen hero can recieve the most glory by getting the furthest through the stage. They do this by throwing blocks on to their opponents screen warping the fourth wall between 2D screen and world space. Blocks have the ability to delay or knock back their opponent with snow avalanches to pursuing ghosts at hand to ensure you can get the lead in the race.Compete as Knight and Damsel across four stages in the campaign mode or simply kick back and enjoy the full selection of blocks via the arcade mode. Knight & Damsel offers a competitive twist on the Damsel in Distress trope fun for all ages.', N'http://cdn.akamai.steamstatic.com/steam/apps/361680/header.jpg?t=1447373192', N'English', N' Multiplayer', N'http://knightanddamsel.com')
