INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Sakura Beach', N'2015', 17, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'True', N'False', N' Indie Simulatio', N'USD', 9.99, 9.99, N'From the makers of Sakura Spirit Sakura Angels and Sakura Fantasy this time working together with the artist Inma to bring you this visual novel dating sim on the beach! Seiji is a daydreamer who spends too much time thinking about space. When he was given a chance to visit the beach with his two childhood friends all he can think about is his chance to take out his telescope and look at the stars. But gradually he begins to realise that his childhood friends want him to pay attention to them instead of the constellations...', N'http://cdn.akamai.steamstatic.com/steam/apps/377680/header.jpg?t=1460935126', N'English', N' Single Player', N'None')
