INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'EVEREST VR(tm)', N'2016', 0, 0, 2, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Simulatio', N'USD', 24.99, 24.99, N'Experience what it feels like to climb Mount Everest in a series of first person challenges as you strive to reach the top of the world. Incomparable visual fidelity combine with player agency in a VR journey that feels both real and emotionally stunning.', N'http://cdn.akamai.steamstatic.com/steam/apps/384750/header.jpg?t=1470153617', N'English**languages with full audio support', N' Single Player', N'http://www.solfar.com')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Dead But Alive! Southern England', N'2015', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Indie Adventure Simulatio', N'USD', 14.99, 14.99, N'Dead But Alive is a zombie survival adventure/simulation set in South England.After a lifetime of danger and daring in the remote battlezones of the 21st century this is the last thing you expected. As an ex-military officer looking to rebuild your relationship with your teenage daughter on simple camping holiday in the rural idyll of southern England you find yourself in a fight for survival in a world devastated by the undead.Separated from your daughter you must use all your hard-won combat leadership and survival skills to unite a small motley team of survivors build a camp scavenge supplies and face untold dangers - all while trying to track her down!The game features a non-linear storyline with moral choices on despair commitment and sacrifice.', N'http://cdn.akamai.steamstatic.com/steam/apps/384840/header.jpg?t=1471032104', N'English', N' Single Player', N'http://www.nielsbauergames.com/deadbutalive.html')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Hack Run ZERO', N'2015', 0, 0, 1, 0, 0, 1, 72, N'False', N'False', N'False', N'True', N'False', N'False', N' Indie Adventure Strategy Simulatio', N'USD', 4.99, 4.99, N'Its time for a SECOND Hack Run! Test your skills again as you hack your way through strange and secretive organizations to discover their hidden agendas! Hack Run ZERO uses old school prompts (like dos and unix) to help you navigate from system to system. As you access users accounts youll discover more and more about the organizations and the people that work there. Your adventure begins when you receive a disturbing ransom note about a loved one. Your only way to set them free is to follow the kidnappers shady demands. Once again your mission is to penetrate the maze of computer accounts through the use of your hacking skills. The stakes run high as you uncover more and more of the enemys diabolical plan; and with over 70 levels theres no guessing how it will all end!', N'http://cdn.akamai.steamstatic.com/steam/apps/384890/header.jpg?t=1447376961', N'English', N' Single Player', N'http://i273.com')
