INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Epic Clicker Journey', N'2016', 0, 0, 1, 0, 0, 1, 40, N'False', N'True', N'False', N'True', N'True', N'True', N' Indie Adventure Casual Free to play', N' ', 0, 0, N'Experience your epic journey. Discover 20 mysterious lands and face the monsters living out there. Show that you are persistent traveler and held your adventure even in the toughest conditions.', N'http://cdn.akamai.steamstatic.com/steam/apps/414730/header.jpg?t=1469605931', N'English Polish French Italian German Spanish Russia', N' Single Player Multiplayer', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Bionite: Origins', N'2015', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Indie Action Strategy EarlyAccess', N'USD', 11.99, 11.99, N'Bionite: Origins is an Action-Strategy game based on hover tank warfare set on various planets and moons throughout the solar system.  Action-Strategy games are also called hybrids because they combine the FPS and RTS elements into the most engaging gaming experience available for the PC. Bionite: Origins integrates the key FPS and RTS elements into one seamless battle experience. Action-Strategy games are the most engaging games to play; because they require strategy to win AND are fun to play because they include the First Person Shooter experience. The game includes 3 maps; The Emze Mine (located on Venus) Biodome 24 (located on Mars) and Hadleys Hope (located on the Moon). This release is a single player version against the computer (Skirmish mode) which involves destroying the enemy base before the enemy destroys your base.  It is also intended to introduce gamers to the complex command system used in the game. There is a learning curve for Bionite: Origins and requires some time to develop the skills necessary to lead a successful campaign against the enemy.  We like to think of the game as Chess on Steroids. It requires players to understand how to develop successful military strategies while relying on vehicle-driving skills to win and advance in rank.Bionite: Origins took over 6 years to develop. There is no DLC all of the content is included in the original release. All future releases of the game are free to people that already have a purchased copy of the game. When the Full Version of the game is released on Steam everyone that purchased a copy of the game in Early Access will get the Fulll Version at no cost. This includes the Multiplayer version all of the turn based missions new content expanded game elements the works!', N'http://cdn.akamai.steamstatic.com/steam/apps/414770/header.jpg?t=1466466973', N'English', N' Single Player', N'http://www.bionitegame.com')
