INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Riding Out', N'2016', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' RPG Simulation EarlyAccess racing Massively Multiplayer', N'USD', 19.99, 19.99, N'Riding Out is a new MMORPG in a world in which everything revolves about horses!Explore the beautiful open world on the back of your horse together with your friends.Experience exciting quests build your own stable and create you own jumping courses dressage competitions and race tracks.Collect herbs and set out your garden to prepare your own food mix.Choose for each of your horses the perfect training based on its individual personality.Mate your own horses or with the horses of the other players to breed your unique and perfect horse.What are you waiting for? Let us ride out!Riding Out is currently in development.Play the Beta now!The beta version will be upgraded regularly with new features. Once the development is complete you have automatically the full version you dont have to purchase it in this case. (You dont have to pay monthly fees to play the game.)', N'http://cdn.akamai.steamstatic.com/steam/apps/461210/header.jpg?t=1471389067', N'English German**languages with full audio support', N' Single Player Multiplayer MMO ', N'http://www.ridingout.de')
