INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Radical Spectrum: Volume 1', N'2016', 0, 0, 1, 0, 0, 1, 0, N'True', N'False', N'False', N'True', N'False', N'True', N' Actio', N'USD', 0.99, 0.99, N'A band of aliens led by the careless Prince FaceBox have invaded the future city of Nucleusport bombarding it with radioactive waste from their own polluted planet. Only one man has the tech and the cojones to fight back. Take on the role of Doc DuBrane and wield his super-powerful Prisma Cannon in this endless arcade-style shooter. Absorb the radiation dropped by the alien ships and fire it right back in their stupid faces. Radical Spectrum is a classically-inspired arcade game with infinitely increasing speed and difficulty featuring a unique color-collecting mechanic that adds a light puzzle element. It will require you to focus your attention on multiple things at once as the bottom of the screen becomes an ever-changing and increasingly difficult bullet-hell landscape while the ultimate goal keeps flying around the top of the screen. And dont forget about the deadly black radiation coursing through the grid. One drop of that and the whole place is toast.', N'http://cdn.akamai.steamstatic.com/steam/apps/486150/header.jpg?t=1468024720', N'English', N' Single Player', N'None')
