INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Watching Grass Grow In VR - The Game', N'2016', 0, 0, 1, 0, 0, 1, 9, N'False', N'False', N'False', N'True', N'False', N'False', N' Indie Actio', N'USD', 4.99, 4.99, N'A thoughtful and inspired VR game about watching grass grow during the end of the world.Rain death and destruction upon your foes with your rocket launcher as you fight to the very end to have the most glorious grass in the world.In this immersive ground-breaking and totally seriously realistic game you will feel the intensity of watching grass grow as you are viciously attacked and your lawn savaged all while the threat of planetary annihilation looms over your head.Do you have what it takes to grow the very best lawn like no one ever grew?The worlds most advanced watching grass grow simulator in virtual reality is now here.The VR game of your dreams has arrived.', N'http://cdn.akamai.steamstatic.com/steam/apps/496230/header.jpg?t=1471934795', N'English', N' Single Player', N'None')
