INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Kubz VR', N'2016', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Indie Casual', N'USD', 3.99, 3.99, N'Kubz brings one of the most famous puzzle game of all time to the Virtual Reality world! Play with an HTC Vive in a 3d rooms with very realistic Tetrominos falling from the sky. Your goal is the plug them in the grid as fast as you can or everything around you will be destroyed. Best of all you can challenge your friends and get to the top of the leaderboard!', N'http://cdn.akamai.steamstatic.com/steam/apps/519940/header.jpg?t=1473167017', N'English**languages with full audio support', N' Single Player', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Naruto Shippuden Uncut: Narutos Growth', N'2016', 0, 0, 0, 0, 0, 0, 0, N'True', N'False', N'False', N'True', N'False', N'False', N'', N'USD', 1.99, 1.99, N'Guy sorely regrets his blunder as his three pupils are imprisoned by the Water Prison. Determined to stop Kisame Guy challenges him using the nunchaku his favorite weapon. Its super taijutsu versus super-human strength.', N'http://cdn.akamai.steamstatic.com/steam/apps/520050/header.jpg?t=1472241911', N'English**languages with full audio support', N'', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Naruto Shippuden Uncut: The Secret Weapon is Called....', N'2016', 0, 0, 0, 0, 0, 0, 0, N'True', N'False', N'False', N'True', N'False', N'False', N'', N'USD', 1.99, 1.99, N'Granny Chiyo and Sakura  rescue Naruto from Itachis genjutsu. Without a moments delay Kakashi begins a counterattack. A high-level ninja battle ensues and Kakashi exhibits his genius ninja prowess by seeing through every subtle tactic. Meanwhile Guy is having a hard time against Kisame but', N'http://cdn.akamai.steamstatic.com/steam/apps/520051/header.jpg?t=1472241939', N'English**languages with full audio support', N'', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Naruto Shippuden Uncut: The Secret of Jinchuriki', N'2016', 0, 0, 0, 0, 0, 0, 0, N'True', N'False', N'False', N'True', N'False', N'False', N'', N'USD', 1.99, 1.99, N'Their vanquished foes Kisame and Itachi turn out to be doppelgangers whose appearance and powers were copied with the Impersonation Jutsu. Chiyo and Kakashi realize that the attack was just a diversion and that the Akatsuki have already begun the process of extracting the Tailed Beast from Gaara.', N'http://cdn.akamai.steamstatic.com/steam/apps/520052/header.jpg?t=1472241967', N'English**languages with full audio support', N'', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Naruto Shippuden Uncut: The Death of Gaara!', N'2016', 0, 0, 0, 0, 0, 0, 0, N'True', N'False', N'False', N'True', N'False', N'False', N'', N'USD', 1.99, 1.99, N'Teams Kakashi and Guy take a short rest. Granny Chiyo watches Naruto dozing off and is reminded of Sasori as a child. The pursuit resumes and when Chiyo wonders why Naruto puts such effort into rescuing Gaara Kakashi explains that Naruto is also a Jinchriki.', N'http://cdn.akamai.steamstatic.com/steam/apps/520053/header.jpg?t=1472241995', N'English**languages with full audio support', N'', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Naruto Shippuden Uncut: Charge Tactic! Button Hook Entry!!', N'2016', 0, 0, 0, 0, 0, 0, 0, N'True', N'False', N'False', N'True', N'False', N'False', N'', N'USD', 1.99, 1.99, N'Teams Kakashi and Guy reach the Akatsuki hideout. They hurry to infiltrate but are thwarted by a five-seal barrier. The only way to break the barrier is to remove all five seals at once. Negi uses his Byakugan to locate the seals and with superb teamwork the Hidden Leaf ninja destroy the barrier.', N'http://cdn.akamai.steamstatic.com/steam/apps/520054/header.jpg?t=1472242026', N'English**languages with full audio support', N'', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Naruto Shippuden Uncut: Traps Activate! Team Guys Enemy', N'2016', 0, 0, 0, 0, 0, 0, 0, N'True', N'False', N'False', N'True', N'False', N'False', N'', N'USD', 1.99, 1.99, N'Breaking the five-seal barrier set off a trap which now has Team Guy battling amazingly accurate copies of themselves. Back at the Akatsuki hideout Deidara and Sasori struggle to take the Nine-Tail Jinch?riki. As Deidara carries off Gaara an angry Naruto goes after him.', N'http://cdn.akamai.steamstatic.com/steam/apps/520055/header.jpg?t=1472242169', N'English**languages with full audio support', N'', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Naruto Shippuden Uncut: Hiruko vs. Two Kunoichi!', N'2016', 0, 0, 0, 0, 0, 0, 0, N'True', N'False', N'False', N'True', N'False', N'False', N'', N'USD', 1.99, 1.99, N'At last the showdown between the old woman and her grandson begins. Sakura is confused by Sasori?s strange appearance and Granny Chiyo explains that this is Hiruko the body that Sasori uses for self-defense. In order to defeat the real Sasori inside the body this Hiruko must first be destroyed.', N'http://cdn.akamai.steamstatic.com/steam/apps/520056/header.jpg?t=1472242198', N' ', N'', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Naruto Shippuden Uncut: Sasoris Real Face', N'2016', 0, 0, 0, 0, 0, 0, 0, N'True', N'False', N'False', N'True', N'False', N'False', N'', N'USD', 1.99, 1.99, N'Granny Chiyo and Sakura manage to expose Sasori who amazingly looks no older than he did twenty years earlier. Chiyo is even more shocked at the second puppet that Sasori produces. It is the human puppet of the Third Kazekage the strongest ninja in Sand history. Sasori it turns out was the maste', N'http://cdn.akamai.steamstatic.com/steam/apps/520057/header.jpg?t=1472242227', N' ', N'', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Naruto Shippuden Uncut: Chiyos Secret Skills', N'2016', 0, 0, 0, 0, 0, 0, 0, N'True', N'False', N'False', N'True', N'False', N'False', N'', N'USD', 1.99, 1.99, N'Sakura is caught by Sasoris tactic and surrounded by a poison cloud. But she uses a Paper Bomb to blow herself free from the poisonous fumes. Her fervent resolve to risk injury to capture Sasori and force him to give up information about Orochimaru resonates in Granny Chiyo?s heart.', N'http://cdn.akamai.steamstatic.com/steam/apps/520058/header.jpg?t=1472242255', N' ', N'', N'None')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Naruto Shippuden Uncut: Father and Mother', N'2016', 0, 0, 0, 0, 0, 0, 0, N'True', N'False', N'False', N'True', N'False', N'False', N'', N'USD', 1.99, 1.99, N'The greatest advantage of the puppets created from humans is that one can take over the jutsu that the human used while alive. Hence the puppet of the Third Kazekage has the special ability to convert chakra into magnetic power.', N'http://cdn.akamai.steamstatic.com/steam/apps/520059/header.jpg?t=1472242343', N' ', N'', N'None')
