INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Dream Dealer', N'2016', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'True', N'True', N' Indie Action Adventure Casual Simulatio', N' ', 0, 0, N'Dream Dealer is a first person exploration game were you take your dream and start a long journey between worlds.Youll never know if what you see is real or if you are in trance.An experimental game made to delight your sensory system.Surreal game inspirate in titles like: The Stanley Parable Dear Esther or Mind: Path to Thalamus were the principal objective is to show what mind isnt able to imagine.It is also a Puzzle game that throws you into a fantastic and surreal environment were your dreams will be difficult to control.The story is explained by inner thoughts that will guide you through your dreams. Sometimes they will try to confuse and deceive you...This game can be described in this words: Walking Simulator Indie Short Atmospheric Casual Story Abstract Adventure Singleplayer  Mystery Experimental Interactive Fiction Horror Psychological Relaxing and Fantasy.', N'http://cdn.akamai.steamstatic.com/steam/apps/532030/header.jpg?t=1475004396', N'English**languages with full audio support', N' Single Player', N'None')
