INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'VRCapture', N'2016', 0, 0, 1, 0, 0, 1, 0, N'True', N'True', N'False', N'True', N'False', N'False', N' Non game', N' ', 0, 0, N'VRCapture is a totally free tool to create amazing VR videos. Perfect for professionals and beginners who really want to pull out great quality videos from vitural world. When you are playing VR games or running VR applications you can record the full scene with VRCapture and create immersive videos for everyone. The recorded video which is immersive can be played on your computer or through HMD. Also YouTube-share option is available. Your family and friends can experience what you have experienced in virtual world with Cardboard or other HMD.', N'http://cdn.akamai.steamstatic.com/steam/apps/544420/header.jpg?t=1477618670', N'English* Simplified Chinese**languages with full audio support', N'', N'None')
