INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'AL*FINE', N'2016', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Indie Casual RPG Simulatio', N' ', 0, 0, N'In this world three races -- humans sprites and kindred -- coexist with their own unique cultures. Some races are on good terms with each other such as humans and sprites while others may not get along as well such as sprites and kindred but they all live together more or less harmoniously.Nowhere is that cooperative attitude more apparent than here in the most commercially-developed town on the archipelago Notte Luce.The tale about to be told is about a boy named Louis and his experiences in Notte Luce.', N'http://cdn.akamai.steamstatic.com/steam/apps/545330/header.jpg?t=1477883281', N'English Japanese', N' Single Player', N'https://sekaiproject.com/products/al-fine/')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Bedfellows FRENZY', N'2017', 0, 0, 1, 0, 0, 1, 0, N'True', N'False', N'False', N'True', N'False', N'False', N' Indie Action Casual', N' ', 0, 0, N'Bedfellows FRENZY is a fast paced arcade style smash and loot. Where you rage through various themed levels demolish buildings tear though the national guard and battle multiple bosses. Crushing and stomping your way to a sick high score and ULTIMATE VICTORY! Play as Monster Form Sheen or Fatigue as you unlock new power-ups and stack them to insane levels build unique style characters for each run with character bonuses cover your shelf with in game trophies achievements and multiple end game cut scenes.Based off the animated series Bedfellows FRENZY sports an original soundtrack of chip tune goodness that sets the tone for each level and mini-game! FRENZY is also a truly twisted yet humorous homage to the arcade classic RAMPAGE.Will Sheen be able to hang in durr? Will Fatigue become a drug addled soccer mom? Play and find out!', N'http://cdn.akamai.steamstatic.com/steam/apps/545430/header.jpg?t=1477704512', N'English**languages with full audio support', N' Single Player Coperativo', N'None')
