INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'7D Game (VR for VIVE)', N'2016', 0, 0, 1, 0, 0, 1, 0, N'False', N'True', N'False', N'True', N'False', N'False', N' Indie Simulation Free to play', N' ', 0, 0, N'Its a game player could use voxels to create different WORLDs. Its a virtual reality game on SteamVR(HTC VIVE). Though the game is highly inspired by such great games like Minecraft and Besiege its specially designed for VR equipment in which there are a fully developed physical system and more importantly an open-source product called Blockly provided by Google to allow players to design and run programs in the game. Because only the games first part was developed and now all its function is not more than a voxel version Tilt Brush. And the upcoming first version of our game will only contain these contents.', N'http://cdn.akamai.steamstatic.com/steam/apps/547440/header.jpg?t=1477536639', N'Simplified Chinese', N' Single Player', N'None')
