INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Zenza', N'2016', 0, 0, 1, 1, 0, 1, 22, N'False', N'False', N'False', N'True', N'False', N'True', N' Indie Casual Strategy', N'USD', 3.99, 3.99, N'Zenza is a calming yet strategic puzzle game based off of Kigo Haiku a form of Japanese poems thematically relating to the seasons. Put colors or shapes together to achieve balance. Progress through increasingly challenging levels to perfect your zen. Leaves blossoms or snow may fall slices and wind by cut your mistakes theres always a chance to start anew.', N'http://cdn.akamai.steamstatic.com/steam/apps/519990/header.jpg?t=1479920720', N'English', N' Single Player', N'http://intropygames.com')
INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Remembering Pearl Harbor', N'2016', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Non game', N'USD', 9.99, 9.99, N'This original immersive virtual-reality project is told through the voice of Lt. James Downing who at 103 is the second-oldest living American veteran to have witnessed that day and is geared towards audiences of all ages. As postmaster of the USS West Virginia Downing gave himself the task of writing letters to the families of men who died or were injured during the attack; those letters form an arc that the user follows through Downings experience of Dec. 7 1941. In an American home of 1941 we hear from Downing about how the coming of war affected everyone in the U.S.; at Pearl Harbor after the attack we see the breadth of the destruction; and in the present day we learn how the experience has stayed with him for 75 years. Throughout the experience users interact with realistic virtual versions of artifacts from the time along with iconic photography and archival video providing a unique and personal view of one of American historys defining moments.', N'http://cdn.akamai.steamstatic.com/steam/apps/520350/header.jpg?t=1481149914', N'English**languages with full audio support', N'', N'http://time.com/lifeVR')
