INSERT [dbo].[juegos] ([Nombre], [ReleaseDate], [RequiredAge], [DemoCount], [DeveloperCount], [DLCCount], [Metacritic], [PublisherCount], [AchievementCount], [ControllerSupport], [IsFree], [FreeVerAvail], [PlatformWindows], [PlatformLinux], [PlatformMac], [Genre], [PriceCurrency], [PriceInitial], [PriceFinal], [ShortDescrip], [HeaderImage], [SupportedLanguages], [Category], [Website]) VALUES (N'Once in Yaissor', N'2016', 0, 0, 1, 0, 0, 1, 0, N'False', N'False', N'False', N'True', N'False', N'False', N' Indie Adventure', N'USD', 0.99, 0.99, N'Leto 2020 god Iaissor. Bolshaia chast liudei stali iutuberami strimerami i prochim skamom pochti nikto ne khochet byt rabotiashchim bydlom. Svoego mneniia nikto ne imeet. Vse vozomnili sebia nigilistami ateistami chitaiushchimi intellektualami i prochei elitoi. No zhizn bydla ne izmenilas ved vse liudi chto goniat na eto bydlo im zhe i iavliaetsia. Poetomu Iaissor bolshe ne Evropa-Aziia teper ona Ateisto-Bydlo. Vo glave Ateisto nakhodiatsia sami liudi a tochnee te kto zanimaetsia internet deiatelnostiu. Vo glave Bydlo stoit Nitup i imenno eta chast strany snabzhaet Rossiiu vsem neobkhodimym proizvodstvom ved v Ateisto zhivut liudi kotorye schitaiut chto rabota dlia otstalykh v razvitii liudei.', N'http://cdn.akamai.steamstatic.com/steam/apps/553790/header.jpg?t=1481305057', N'Russia', N' Single Player', N'None')
